\n      let settingsNavIconSupported = false;\n\n      const mountSettingsSection = () => {\n        if (!settingsSectionSupported || offSettingsSection) return;\n        if (sidebarController && !sidebarController.isSettingsSectionEnabled()) return;\n        try {\n          const unreg = ctx.slots.register({ name: \"settings.section\", id: \"skills-manager\", order: 25, label: function () { return ctx.locale.bind(NS)(\"title\"); }, icon: \"skill\", locale: NS }, SkillManagerSection);\n          offSettingsSection = typeof unreg === \"function\" ? (unreg as () => void) : () => {};\n        } catch (reason) {\n          console.warn(\"skills-manager: register settings.section failed:\", reason);\n          offSettingsSection = null;\n        }\n      };\n\n      const unmountSettingsSection = () => {\n        if (offSettingsSection) {\n          try { offSettingsSection(); } catch {}\n          offSettingsSection = null;\n        }\n      };\n\n      // 图标槽位的唯一注册入口：inject 声明回调与入口位置同步都走这里，避免两处语句漂移\n      const registerSettingsNavIcon = () => {\n        if (offSettingsNavIcon) return true;\n        try {\n          const unreg = (ctx.slots.register as any)({\n            name: \"settings.section.icon\",\n            id: \"skills-manager\",\n            locale: NS,\n          }, SkillsNavIcon);\n          offSettingsNavIcon = typeof unreg === \"function\" ? (unreg as () => void) : () => {};\n          return true;\n        } catch (reason) {\n          console.warn(\"skills-manager: register settings.section.icon failed:\", reason);\n          offSettingsNavIcon = null;\n          return false;\n        }\n      };\n\n      const mountSettingsNavIcon = () => {\n        if (!settingsNavIconSupported) return;\n        if (sidebarController && !sidebarController.isSettingsSectionEnabled()) return;\n        registerSettingsNavIcon();\n      };\n\n      const unmountSettingsNavIcon = () => {\n        const unreg = offSettingsNavIcon;\n        offSettingsNavIcon = null;\n        if (!unreg) return;\n        try { unreg(); } catch {}\n      };\n\n      const syncSettingsSection = () => {\n        if (sidebarController?.isSettingsSectionEnabled?.() ?? true) {\n          mountSettingsSection();\n          mountSettingsNavIcon();\n        } else {\n          unmountSettingsSection();\n          unmountSettingsNavIcon();\n        }\n      };\n\n      // 对齐 codex-pet 与 dsh-im-connect：宿主声明 settings.section.icon 时才注册；\n      // 老宿主不声明该槽位，inject 回调永不触发，也就不存在 register 抛错。\n      if (typeof ctx.slots?.inject === \"function\") {\n        try {\n          (ctx.slots.inject as any)(\"settings.section.icon\", function () {\n            settingsNavIconSupported = true;\n            // 声明撤销时宿主会清空该槽位的全部条目，本地句柄必须一起归零：\n            // 留着 stale 句柄会让后续 mount 提前 return，图标再也回不来。\n            const releaseDeclaration = function () {\n              settingsNavIconSupported = false;\n              unmountSettingsNavIcon();\n            };\n            if (sidebarController && !sidebarController.isSettingsSectionEnabled()) return releaseDeclaration;\n            if (!registerSettingsNavIcon()) return releaseDeclaration;\n            return releaseDeclaration;\n          });\n        } catch (reason) {\n          console.warn(\"skills-manager: inject settings.section.icon failed:\", reason);\n        }\n      }\n\n      ctx.slots.inject(\"settings.section\", function () {\n        settingsSectionSupported = true;\n        try {\n          if (sidebarController && !sidebarController.isSettingsSectionEnabled()) {\n            return function () {\n              settingsSectionSupported = false;\n              unmountSettingsSection();\n            };\n          }\n          const unreg = ctx.slots.register({ name: \"settings.section\", id: \"skills-manager\", order: 25, label: function () { return ctx.locale.bind(NS)(\"title\"); }, icon: \"skill\", locale: NS }, SkillManagerSection);\n          offSettingsSection = typeof unreg === \"function\" ? (unreg as () => void) : () => {};\n          return unreg;\n        } catch (reason) {\n          console.warn(\"skills-manager: register settings.section failed:\", reason);\n          return function () {\n            settingsSectionSupported = false;\n          };\n        }\n      });\n      sidebarController = setupSidebarEntry(ctx, {\n        callApi: callApi,\n        headers: MUTATION_HEADERS,\n        renderPanel: function (ownerProps?: any) { return h(SkillManagerSection, Object.assign({ t: ctx.locale.bind(NS) }, ownerProps)); },\n        ns: NS,\n        onLocationChange: function () {\n          syncSettingsSection();\n        }\n      });\n      ctx.effect(function () {\n        return function () {\n          if (sidebarController && typeof sidebarController.destroy === \"function\") {\n            sidebarController.destroy();\n            sidebarController = undefined;\n          }\n          unmountSettingsNavIcon();\n          unmountSettingsSection();\n        };\n      }, \"skills-manager: sidebar entry cleanup\");\n    }\n    module.exports.formatTrashTime = formatTrashTime; module.exports.DICT = DICT; module.exports.translateError = translateError; module.exports.parseApiResponse = parseApiResponse; module.exports.resolveApiUrl = resolveApiUrl; module.exports.resolveRepoBrand = resolveRepoBrand; module.exports.skillDeclaredInvocationKind = skillDeclaredInvocationKind; module.exports.isSkillEnabled = isSkillEnabled; module.exports.countKey = countKey; module.exports.rootDisplayName = rootDisplayName; module.exports.summarizeImportResult = summarizeImportResult; module.exports.normalizeSkillQuery = normalizeSkillQuery; module.exports.matchSkillQuery = matchSkillQuery; module.exports.filterSkills = filterSkills; module.exports.visibleSkillRoots = visibleSkillRoots; module.exports.scopeSkillRoots = scopeSkillRoots; module.exports.skillStatus = skillStatus; module.exports.countSkillStatuses = countSkillStatuses; module.exports.currentSessionId = currentSessionId; modul